# Part D: SEC stadium and arena naming status (second research pass of 18 Nov 2026). All seven are honorific or donor names.
def _named(school,pre,partner,src,url,note):
    return [(school,pre+'_partner',partner,'2026',src,url,note),(school,pre+'_deal_type','honorific','2026',src,url,note)]
ROWS_D=[]
ROWS_D+=_named('Alabama','stadium_nr','George Denny and Paul "Bear" Bryant (honorees)',"Encyclopedia of Alabama, Bryant-Denny Stadium",'https://encyclopediaofalabama.org/?p=4501',"‘Bryant-Denny Stadium in Tuscaloosa, named for former University of Alabama president George Denny and legendary football coach Paul \"Bear\" Bryant’; ‘It was constructed in 1929 as Denny Stadium, and in 1975 the state legislature renamed it to honor Bryant.’")
ROWS_D+=_named('Texas','stadium_nr','Darrell K Royal (honoree)',"Texas State Historical Association, Handbook of Texas",'https://www.tshaonline.org/handbook/entries/darrell-k-royal-texas-memorial-stadium',"‘In 1996 the university again honored its legendary football coach by renaming the stadium the Darrell K Royal–Texas Memorial Stadium.’ The stadium was first dedicated to Texans who served in World War I.")
ROWS_D+=_named('Alabama','arena_nr','Jefferson Coleman (honoree)',"University of Alabama Libraries, Cool@Hoole (11 May 2015)",'https://apps.lib.ua.edu/blogs/coolathoole/?p=3818',"‘In 1988, it was named in honor of Jefferson Coleman, a prominent alumnus who held many positions at the university, including Business Manager of the football team and Director of Alumni Affairs.’")
ROWS_D+=_named('Arkansas','arena_nr','Bud Walton (donor)',"University of Arkansas Facilities Management, request for qualifications (17 Mar 2023)",'https://fama.uark.edu/campus-planning/capital-budgeting/2023_rfq_arch_budwaltonarenarenovation.pdf',"‘Bud Walton Arena opened in November 1993 thanks to the vision of Athletic Director Frank Broyles and the generous support of Walmart co-founder Bud Walton’. A donor name, not a paid naming-rights deal; the Northwest Arkansas Democrat-Gazette (5 Nov 2017) reports ‘Walton contributed $15 million.’")
ROWS_D+=_named('Auburn','arena_nr','Bill and Connie Neville (donors)',"Associated Press via Whole Hog Sports (8 Feb 2022)",'https://www.wholehogsports.com//news/2022/feb/08/auburn-to-rename-basketball-arena/',"‘Auburn will rename its basketball arena in honor of a couple who made the largest single gift to the athletics program.’ ‘It will be named after Bill and Connie Neville, a change approved by the Board of Trustees.’ ‘The university did not disclose the amount of the donation.’")
ROWS_D+=_named('Mississippi State','arena_nr','George Duke Humphrey (honoree)',"Mississippi State Athletics, Humphrey Coliseum facility page",'https://new.express.adobe.com/webpage/Z4X7VDY2jmbME',"‘Named in honor of George Duke Humphrey, a former Mississippi State president (1934-45), the Coliseum opened in 1975.’")
ROWS_D+=_named('Texas','arena_nr','Moody Foundation (donor)',"UT News (9 Nov 2019)",'https://news.utexas.edu/?p=136050',"‘The University of Texas at Austin's new basketball arena and events center will be named Moody Center in honor of a $130 million grant to UT from the Moody Foundation’; ‘the single largest gift from a foundation in the university's history’. The university describes it as a grant and a gift, not a naming-rights contract, so it is classed as a donor name. The Daily Texan (11 Nov 2019) reports the grant ‘will be paid over the course of 20 years in $6 to $7 million amounts.’")
